SELECT a.paper_position_id, a.close_trigger, s.id AS src_id, s.interval_code AS src_interval, s.candle_open_time AS src_candle, s.generated_at AS src_generated, s.decision AS src_decision, (SELECT CONCAT(f.id,'|',f.candle_open_time,'|',f.generated_at,'|',f.decision) FROM crypto_ai.trade_signal f WHERE f.symbol = a.symbol AND f.interval_code = '5m' AND f.generated_at <= p.closed_at ORDER BY f.generated_at DESC LIMIT 1) AS last_5m, (SELECT CONCAT(h.id,'|',h.candle_open_time,'|',h.generated_at,'|',h.decision) FROM crypto_ai.trade_signal h WHERE h.symbol = a.symbol AND h.interval_code = '1h' AND h.generated_at <= p.closed_at ORDER BY h.generated_at DESC LIMIT 1) AS last_1h FROM crypto_ai.production_exit_audit a JOIN crypto_ai.paper_position p ON p.id = a.paper_position_id LEFT JOIN crypto_ai.trade_signal s ON s.id = a.source_signal_id WHERE a.paper_position_id IN (182,172,162,158,143,137) LIMIT 6